# -*- coding: utf-8 -*-
from common import md, esc, cq, wq, sq
from p_hist import tbl
T=[("d1","👑","基督的位格：真神真人","约翰说“道成了肉身”（{{约1:14}}）；耶稣赦罪（{{可2:5-7}}）、接受敬拜（{{太14:33}}）、称“还没有亚伯拉罕就有了我”（{{约8:58}}），多马称祂“我的主，我的神”（{{约20:28}}）。同一位又饥饿（{{太4:2}}）、疲倦（{{约4:6}}）、哭泣（{{约11:35}}）、在客西马尼极其忧伤（{{可14:34}}）。",
    "约1:1-18；可2:1-12；约5:18；约10:30；约20:28；路2:52；约11:35",[("bc",19,"正因如此，我们宣告基督是真神，也是真人。他是真神，为要藉着他的大能胜过死亡；他也是真人，所以才能以他软弱的肉体为我们受死。"),("bc",10,"他不是从取了我们人性那一刻起才成为神的儿子，而是在永恒中就是神的儿子")],('wcf',8,2)),
  ("d2","🔱","三重职分：先知、祭司、君王","“基督”意为“受膏者”：旧约先知、祭司、君王都被膏立。耶稣是**先知**——“你们要听他”（{{太17:5}}）；是**祭司**——“作多人的赎价”（{{可10:45}}），并为门徒代求（{{约17}}）；是**君王**——“天上地下所有的权柄都赐给我了”（{{太28:18}}）。","太17:5；路4:18-21；可10:45；约17；太21:5；太28:18",[("hc",31),("hc",32)],('wsc',23)),
  ("d3","🌾","神的国（天国）","耶稣宣讲的中心：天国**已经临到**（{{太12:28}}；{{路17:21}}）又**将要来**（{{太6:10}}；{{太25:31-34}}）；它像芥菜种与面酵从小变大（{{太13:31-33}}）；进入天国要重生（{{约3:3-5}}）、像小孩子（{{可10:15}}）。","太4:17；太13；可1:15；路17:20-21；约3:3-5；约18:36",[("hc",123)],None),
  ("d4","✝️","十字架：代赎与满足","耶稣自己解释祂的死：“赎价”（{{可10:45}}）、“立约的血，为多人流出来，使罪得赦”（{{太26:28}}）、“好牧人为羊舍命”（{{约10:11}}）。在十字架上祂呼喊“为什么离弃我”（{{可15:34}}），承受神的忿怒；最后说“成了”（{{约19:30}}）——工作完全成就。","可10:45；太26:28；约1:29；约10:11-18；可15:34；约19:30",[("hc",37),("dort",2,2)],None),
  ("d5","🌅","复活与升天","四卷福音书都以空坟作结；复活证明父接纳了子的献祭，也是信徒复活的保证（{{约11:25}}）。升天后祂坐在父的右边，作我们的中保，并赐下圣灵（{{约16:7}}；{{路24:49-51}}）。","太28；可16；路24；约20–21；约14:2-3；约16:7",[("hc",45),("hc",49)],None),
  ("d6","🕊️","圣灵与重生","“人若不是从水和圣灵生的，就不能进神的国”（{{约3:5}}）；圣灵是“保惠师”，要叫人为罪、为义、为审判自己责备自己（{{约16:8}}），并引导门徒明白一切的真理（{{约16:13}}）。","约3:1-8；约7:37-39；约14:16-17,26；约16:7-15；约20:22；路11:13",[("hc",53),("dort",3,12,"归信就是重生，是成为新造的人，是从死里复活。")],('wcf',10,1)),
  ("d7","🌷","拣选与有效呼召","“凡父所赐给我的人必到我这里来”（{{约6:37}}）；“若不是差我来的父吸引人，就没有能到我这里来的”（{{约6:44}}）；“不是你们拣选了我，是我拣选了你们”（{{约15:16}}）；“我的羊听我的声音”（{{约10:27}}）。","约6:37-44；约10:26-29；约15:16；约17:2,6,9；太11:25-27；太22:14",[("dort",1,7,"拣选是神不变的旨意。"),("dort",3,11)],None),
  ("d8","📜","律法的成全","耶稣成全律法（{{太5:17}}），把律法总结为爱神爱人（{{太22:37-40}}），并以完全的顺服为我们满足律法的要求。礼仪律的影儿在祂身上应验；道德律成为蒙恩之人感恩生活的准则。","太5:17-48；太22:34-40；可7:1-23；可2:23-28；约1:17",[("bc",25),("hc",115)],None),
  ("d9","⛪","教会与圣礼","耶稣建立教会（{{太16:18}}），赐下天国钥匙与纪律（{{太18:15-20}}）；设立洗礼（{{太28:19}}）与圣餐（{{路22:19-20}}）作为恩典之约的记号与印证。","太16:18-19；太18:15-20；太28:19；路22:19-20；约13–17",[("hc",54),("hc",65),("bc",34,"出于这个原因，神吩咐说一切属他的人都要用清水受洗归入圣父、圣子、圣灵的名（参见太28:19）。"),("hc",75)],None),
  ("d10","⏳","末世：再来与审判","人子要在荣耀里降临，审判万民（{{太25:31-46}}）；“那日子、那时辰没有人知道”（{{太24:36}}），所以要儆醒（{{太25:13}}）；信的人“出死入生”（{{约5:24}}），将来身体复活（{{约5:28-29}}）。","太24–25；可13；路21；约5:24-29；约14:1-3",[("bc",37,"最后，我们相信，正如圣经所说的，当主所定的那日子、那时辰来到时——那日子、那时辰无人知道，当被选的人数添满时，我们的主耶稣基督将在大荣耀和威严中，有形有体地从天降临，正如他升天时那样（徒1:11）。"),("hc",52)],None)]
def build():
    b=['<div class="dmap glass reveal"><div class="dm-c">✝️ 福音书教义<br><small>十大主题</small></div><div class="dm-r">'+"".join(f'<a href="#{i}" class="dm-n" style="--i:{k}">{ic} {t}</a>' for k,(i,ic,t,*_) in enumerate(T))+'</div></div>']
    for i,ic,t,s,refs,qs,w in T:
        b.append(f'<h2 id="{i}">{ic} {t}</h2><div class="card glass"><p>{md(s)}</p><p class="refs">📖 主要经文：{esc(refs)}</p></div>')
        ww=""
        if w: ww=wq(w[0],w[1],w[2]) if w[0]=='wcf' else wq(w[0],w[1])
        b.append('<div class="confs">'+"".join(cq(q) for q in qs)+ww+'</div>')
        if i=="d1":
            b.append('<h3 id="d1b">🧱 古代基督论异端与正统</h3>'+tbl(["错误","主张","福音书的回答","信经/信条"],[["幻影派","基督只是看似有身体","“摸我看看！魂无骨无肉，你们看，我是有的”（路24:39）","使徒信经“从童贞女马利亚所生”"],["亚流派","子是受造的，不是永恒的神","“太初有道……道就是神”（约1:1）","尼西亚信经“受生却非被造，与父同质”"],["阿波利拿留派","基督没有人的理性灵魂","“我心里甚是忧伤，几乎要死”（太26:38）","亚他那修信经“具有人的灵魂和肉体的完全的人”"],["聂斯脱利派","两性分成两个位格","同一位既睡在船上，又斥责风浪（可4:38-39）","BC 19：二性联合于一个位格"],["欧迪奇派","人性被神性吞没成一性","“耶稣的智慧和身量……都一齐增长”（路2:52）","BC 19：二性各保其属性"]]))
        if i=="d3": b.append(sq("/sermons/heidelberg-catechism/lord-day-48","基督的传道决定了教会的祷告！基督说：天国近了。天国就要临到了，因此我们祷告说：愿你的国降临！"))
    b.append('<h2 id="dw">📙 三项联合信条 vs 威斯敏斯特标准：侧重比较</h2>')
    R=[("圣约结构","在洗礼、儿女、拣选中运用圣约语言；未单列“行为之约”","第 7 章明确区分行为之约与恩典之约"),("风格","海德堡：个人、敬拜性（“我唯一的安慰”）","系统、精确、逻辑性强"),("结构","HC：罪—救—恩（像罗马书）","从圣经、神论到末世的系统次序"),
       ("基督的职分","HC 31：先知、祭司、君王，并以此说明“基督徒”之名（HC 32）","WSC 23–26、WCF 8 章：中保的职分"),("拣选的表述","多特：牧养性（确据、安慰）","第 3 章：预旨的完整论述"),("教会政体","BC 30–32：牧师、长老、执事组成议会","长老会体制，区会、大会")]
    b.append('<div class="tbl"><table><thead><tr><th>主题</th><th>三项联合信条（欧陆）</th><th>威斯敏斯特标准（长老会）</th></tr></thead><tbody>'+"".join(f'<tr><td><b>{a}</b></td><td>{c}</td><td>{d}</td></tr>' for a,c,d in R)+'</tbody></table></div><p class="note">两者在教义实质上一致（同属改革宗正统），差异主要在表述侧重与历史处境。北美的 URCNA、CanRC、HRC、PRC 采用三项联合信条；OPC 采用威斯敏斯特标准。</p>')
    return "".join(b)
